class Point { constructor(x, y) { this.y = y; this.x = x; } sum(k) { return this.x + this.y + k; } static of(x) { return new Point(x, x); } get first() { return this.x; } set first(v) { this.x = v; } };
exports.Point = Point;
function Old(a) { if (!(this instanceof Old)) return new Old(a); this.a = a; }
Old.prototype.twice = function (k) { return [this.a, this.a, k.length]; };
Old.make = function (a) { return new Old(a); };
exports.Old = Old;
class Factory { constructor(kind) { if (kind === "other") return { made: "another object" }; this.kind = kind; } who() { return this.kind; } };
exports.Factory = Factory;
class Late { constructor(n) { if (n > 1) this.big = true; this.n = n; } grow(name) { this[name] = name; return Object.keys(this); } };
exports.Late = Late;
class Sub extends Point { constructor(x) { super(x, "y of Sub"); this.extra = x; } sum(k) { return "Sub:" + super.sum(k); } };
exports.Sub = Sub;
class Generic { constructor(held) { this.held = held; } get() { return this.held; } put(held) { this.held = held; return this; } };
exports.Generic = Generic;
class Private { #held; constructor(held) { this.#held = held; } #twice(k) { return [this.#held, k]; } twice(k) { return this.#twice(k); } static is(o) { return #held in o; } };
exports.Private = Private;
function takes_point(p) { return [p.x, p.y, typeof p.sum === "function" ? p.sum(1) : "no sum", p instanceof Point]; };
exports.takes_point = takes_point;
function takes_old(o) { return [o.a, o instanceof Old]; };
exports.takes_old = takes_old;
function takes_other_class(p) { return [p.x, p.a, p.kind]; };
exports.takes_other_class = takes_other_class;
function writes_point(p) { p.x = "written"; p.w = 1; return Object.keys(p); };
exports.writes_point = writes_point;
function makes_point(x) { return x === 1 ? new Point(1, 2) : x === 2 ? { x: "plain", y: 0 } : null; };
exports.makes_point = makes_point;
function reads_made(x) { const p = makes_point(x); return p && [p.x, p.y]; };
exports.reads_made = reads_made;
